+
+test('GET /notes returns newest first, by instant', async () => {
+  for (const createdAt of ['2026-01-01T09:00:00Z', '2026-01-01T08:00:00Z', '2026-01-01T10:00:00+03:00', '2026-01-02T00:00:00Z']) {
+    await call('POST', '/notes', 'sirali', { title: createdAt, createdAt });
+  }
+  const list = (await (await call('GET', '/notes', 'sirali')).json()).filter((n) => n.owner === 'sirali');
+  assert.deepEqual(list.map((n) => n.createdAt), ['2026-01-02T00:00:00Z', '2026-01-01T09:00:00Z', '2026-01-01T08:00:00Z', '2026-01-01T10:00:00+03:00']);
+});
+
+test('a note with an invalid createdAt is rejected', async () => {
+  assert.equal((await call('POST', '/notes', 'ayse', { title: 'x', createdAt: 'dün' })).status, 400);
+});

